package tw.com.tft.documentscanner.util; import android.app.*;import android.graphics.*;import android.view.*;import androidx.core.graphics.Insets;import androidx.core.view.*; public final class UiUtils{public static void applyInsets(Activity a,View r,boolean light){Window w=a.getWindow();WindowCompat.setDecorFitsSystemWindows(w,false);WindowCompat.getInsetsController(w,w.getDecorView()).setAppearanceLightStatusBars(light);int l=r.getPaddingLeft(),t=r.getPaddingTop(),rr=r.getPaddingRight(),b=r.getPaddingBottom();ViewCompat.setOnApplyWindowInsetsListener(r,(v,i)->{Insets s=i.getInsets(WindowInsetsCompat.Type.systemBars());v.setPadding(l+s.left,t+s.top,rr+s.right,b+s.bottom);return i;});}public static int parseAccent(String n){if("mint".equals(n))return Color.parseColor("#18A77B");if("orange".equals(n))return Color.parseColor("#E8891C");if("black".equals(n))return Color.parseColor("#1E1E1E");return Color.parseColor("#2368D9");}}